  addMessage("Eu sou um chatbot de teste, estou aqui para responder a suas perguntas. Qual é o seu problema?", true);
  addMessage("Meu problema é que eu não sei como usar este site.", false);
  addMessage("Desculpe, mas esta função não está disponível no momento. Por favor, tente novamente mais tarde ou contate o suporte do site para obter ajuda. ", true);
}

// Feche o modal
function closeChatHistory() {
  modalOverlay.style.display = "none";
}

// Adicione eventos de clique para exibir e fechar o modal
